import { test, expect } from '@playwright/test';

test.describe('Splash — экран входа', () => {
  test('SP-01 Splash: бренд, обещание, пасук, одна кнопка → /phone #6a86f800 @prod-safe', async ({ page }) => {
    // 1. Открыть `/`.
    await page.goto('/');
    await expect(page.getByRole('button', { name: 'בואו נתחיל' })).toBeVisible();

    // 2. Прочитать тексты, кнопки, поля ввода.
    await expect(page.getByText('אור הגאולה', { exact: true })).toBeVisible();
    await expect(page.getByText('ה\' רֹעִי לֹא אֶחְסָר', { exact: true })).toBeVisible();
    await expect(page.getByText('ברוכים הבאים לאור הגאולה', { exact: true })).toBeVisible();
    await expect(page.getByText('התפילה החכמה שתלווה אותך בכל מקום ובכל זמן', { exact: true })).toBeVisible();
    await expect(page.getByRole('button')).toHaveCount(1);
    await expect(page.getByRole('button', { name: 'בואו נתחיל' })).toHaveCount(1);
    await expect(page.locator('input')).toHaveCount(0);
    const noHScroll = await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth);
    expect(noHScroll).toBe(true);

    // 3. Нажать «בואו נתחיל».
    await page.getByRole('button', { name: 'בואו נתחיל' }).click();
    await expect(page).toHaveURL(/\/phone$/);
  });
});
